                                .name(securitySchemeName)
                                .type(SecurityScheme.Type.HTTP)
                                .scheme("bearer")
                                .bearerFormat("JWT")));
    }
}

package com.devops.qvs.service;

import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Service;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.time.LocalDate;

@Service
public class CryptoHashService {

    @Value("${app.crypto.salt:QVS-DEFAULT-SALT}")
    private String salt;

    /**
     * Calculates a deterministic, tamper-evident SHA-256 cryptographic hash of qualification data.
     */
    public String generateFingerprint(String certificateNumber,
                                      String studentFullName,
                                      String studentIdNumber,
                                      String awardTitle,
                                      String institutionCode,
                                      LocalDate awardDate) {
        String payload = String.format("%s|%s|%s|%s|%s|%s|%s",
                certificateNumber.trim().toUpperCase(),
                studentFullName.trim().toUpperCase(),
                studentIdNumber.trim().toUpperCase(),
                awardTitle.trim().toUpperCase(),
                institutionCode.trim().toUpperCase(),
                awardDate.toString(),
                salt);

        return sha256(payload);
    }

    /**
     * Verifies if given qualification parameters match an expected digital fingerprint.
     */
    public boolean verifyFingerprint(String certificateNumber,
                                     String studentFullName,
                                     String studentIdNumber,
                                     String awardTitle,
                                     String institutionCode,
                                     LocalDate awardDate,
                                     String expectedFingerprint) {
        String computed = generateFingerprint(certificateNumber, studentFullName, studentIdNumber, awardTitle, institutionCode, awardDate);
        return computed.equalsIgnoreCase(expectedFingerprint);
    }

    private String sha256(String base) {
        try {
            MessageDigest digest = MessageDigest.getInstance("SHA-256");
            byte[] hash = digest.digest(base.getBytes(StandardCharsets.UTF_8));
            StringBuilder hexString = new StringBuilder();
            for (byte b : hash) {
                String hex = Integer.toHexString(0xff & b);
                if (hex.length() == 1) {
                    hexString.append('0');
                }
                hexString.append(hex);
            }
            return hexString.toString();
        } catch (NoSuchAlgorithmException e) {
            throw new RuntimeException("SHA-256 algorithm not available", e);
        }
    }
}

package com.devops.qvs.service;

import com.devops.qvs.dto.AuditLogDto;
import com.devops.qvs.model.AuditLog;
import com.devops.qvs.model.VerificationStatus;
import com.devops.qvs.repository.AuditLogRepository;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.time.LocalDateTime;
import java.util.List;
import java.util.stream.Collectors;

@Service
public class AuditLogService {

    private final AuditLogRepository auditLogRepository;

    public AuditLogService(AuditLogRepository auditLogRepository) {
        this.auditLogRepository = auditLogRepository;
    }

    @Transactional
    public AuditLog recordAuditLog(String queryParam,
                                   VerificationStatus status,
                                   String verifierIdentifier,
                                   String ipAddress,
                                   String userAgent,
                                   String certNumber,
                                   String institutionName,
                                   String details) {
        AuditLog log = AuditLog.builder()
                .queryParameter(queryParam)
                .verificationOutcome(status)
                .verifierIdentifier(verifierIdentifier != null ? verifierIdentifier : "Anonymous Public Verifier")
                .ipAddress(ipAddress != null ? ipAddress : "127.0.0.1")
                .userAgent(userAgent != null ? userAgent : "Web-Client")
                .certificateNumber(certNumber)
                .institutionName(institutionName)
                .details(details)
                .timestamp(LocalDateTime.now())
                .build();

        return auditLogRepository.save(log);
    }

    @Transactional(readOnly = true)
    public List<AuditLogDto> getRecentAuditLogs() {
        return auditLogRepository.findTop50ByOrderByTimestampDesc()
                .stream()
                .map(this::mapToDto)
                .collect(Collectors.toList());
    }

    @Transactional(readOnly = true)
    public List<AuditLogDto> getLogsByCertificateNumber(String certificateNumber) {
        return auditLogRepository.findByCertificateNumber(certificateNumber)
                .stream()
                .map(this::mapToDto)
                .collect(Collectors.toList());
    }

    private AuditLogDto mapToDto(AuditLog log) {
        return AuditLogDto.builder()
                .id(log.getId())
                .queryParameter(log.getQueryParameter())
                .verificationOutcome(log.getVerificationOutcome())
                .verifierIdentifier(log.getVerifierIdentifier())
                .ipAddress(log.getIpAddress())
                .userAgent(log.getUserAgent())
                .certificateNumber(log.getCertificateNumber())
                .institutionName(log.getInstitutionName())
                .details(log.getDetails())
                .timestamp(log.getTimestamp())
                .build();
    }
}

package com.devops.qvs.service;

import com.devops.qvs.config.JwtUtils;
import com.devops.qvs.dto.AuthRequest;
import com.devops.qvs.dto.AuthResponse;
import com.devops.qvs.dto.RegisterRequest;
import com.devops.qvs.exception.BadRequestException;
import com.devops.qvs.exception.ResourceNotFoundException;
import com.devops.qvs.model.Institution;
import com.devops.qvs.model.User;
import com.devops.qvs.repository.InstitutionRepository;
import com.devops.qvs.repository.UserRepository;
import org.springframework.security.authentication.AuthenticationManager;
import org.springframework.security.authentication.UsernamePasswordAuthenticationToken;
import org.springframework.security.core.Authentication;
import org.springframework.security.core.context.SecurityContextHolder;
import org.springframework.security.core.userdetails.UserDetails;
import org.springframework.security.crypto.password.PasswordEncoder;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service
public class AuthService {

    private final AuthenticationManager authenticationManager;
    private final UserRepository userRepository;
    private final InstitutionRepository institutionRepository;
    private final PasswordEncoder passwordEncoder;
    private final JwtUtils jwtUtils;

    public AuthService(AuthenticationManager authenticationManager,
                       UserRepository userRepository,
                       InstitutionRepository institutionRepository,
                       PasswordEncoder passwordEncoder,
                       JwtUtils jwtUtils) {
        this.authenticationManager = authenticationManager;
        this.userRepository = userRepository;
        this.institutionRepository = institutionRepository;
        this.passwordEncoder = passwordEncoder;
        this.jwtUtils = jwtUtils;
    }

    public AuthResponse authenticate(AuthRequest request) {
        Authentication authentication = authenticationManager.authenticate(
                new UsernamePasswordAuthenticationToken(request.getUsername(), request.getPassword()));

        SecurityContextHolder.getContext().setAuthentication(authentication);
        UserDetails userDetails = (UserDetails) authentication.getPrincipal();
        String jwt = jwtUtils.generateToken(userDetails);

        User user = userRepository.findByUsername(userDetails.getUsername())
                .orElseThrow(() -> new ResourceNotFoundException("User not found: " + userDetails.getUsername()));

        return AuthResponse.builder()
                .token(jwt)
                .id(user.getId())
                .username(user.getUsername())
                .email(user.getEmail())
                .fullName(user.getFullName())
                .role(user.getRole())
                .institutionName(user.getInstitution() != null ? user.getInstitution().getName() : null)
                .build();
    }

    @Transactional
    public AuthResponse register(RegisterRequest request) {
        if (userRepository.existsByUsername(request.getUsername())) {
            throw new BadRequestException("Error: Username is already taken!");
        }

        if (userRepository.existsByEmail(request.getEmail())) {
            throw new BadRequestException("Error: Email is already in use!");
        }

        Institution institution = null;
        if (request.getInstitutionId() != null) {
            institution = institutionRepository.findById(request.getInstitutionId())
                    .orElseThrow(() -> new ResourceNotFoundException("Institution not found with id: " + request.getInstitutionId()));
        }

        User user = User.builder()
                .username(request.getUsername())
                .email(request.getEmail())
                .password(passwordEncoder.encode(request.getPassword()))
                .fullName(request.getFullName())
                .role(request.getRole())
                .institution(institution)
                .enabled(true)
                .build();

        userRepository.save(user);

        // Auto authenticate after registration
        return authenticate(new AuthRequest(request.getUsername(), request.getPassword()));
    }
}

package com.devops.qvs.service;

import com.devops.qvs.dto.QualificationRequest;
import com.devops.qvs.dto.QualificationResponse;
import com.devops.qvs.exception.BadRequestException;
import com.devops.qvs.exception.ResourceNotFoundException;
import com.devops.qvs.model.Institution;
import com.devops.qvs.model.Qualification;
import com.devops.qvs.model.QualificationStatus;
import com.devops.qvs.repository.InstitutionRepository;
import com.devops.qvs.repository.QualificationRepository;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.time.LocalDateTime;
import java.util.List;
import java.util.stream.Collectors;

@Service
public class QualificationService {

    private final QualificationRepository qualificationRepository;
    private final InstitutionRepository institutionRepository;
    private final CryptoHashService cryptoHashService;

    public QualificationService(QualificationRepository qualificationRepository,
                                InstitutionRepository institutionRepository,
                                CryptoHashService cryptoHashService) {
        this.qualificationRepository = qualificationRepository;
        this.institutionRepository = institutionRepository;
        this.cryptoHashService = cryptoHashService;
    }

    @Transactional
    public QualificationResponse registerQualification(QualificationRequest request) {
        if (qualificationRepository.existsByCertificateNumber(request.getCertificateNumber())) {
            throw new BadRequestException("Qualification with certificate number " + request.getCertificateNumber() + " already exists.");
        }

        Institution institution = institutionRepository.findById(request.getInstitutionId())
                .orElseThrow(() -> new ResourceNotFoundException("Institution not found with id: " + request.getInstitutionId()));

        String fingerprint = cryptoHashService.generateFingerprint(
                request.getCertificateNumber(),
                request.getStudentFullName(),
                request.getStudentIdNumber(),
                request.getAwardTitle(),
                institution.getInstitutionCode(),
                request.getAwardDate()
        );

        Qualification qualification = Qualification.builder()
                .certificateNumber(request.getCertificateNumber().trim().toUpperCase())
                .studentFullName(request.getStudentFullName().trim())
                .studentIdNumber(request.getStudentIdNumber().trim())
                .awardTitle(request.getAwardTitle().trim())
                .majorSpecialization(request.getMajorSpecialization().trim())
                .classification(request.getClassification().trim())
                .awardDate(request.getAwardDate())
                .institution(institution)
                .status(QualificationStatus.ACTIVE)
                .digitalFingerprint(fingerprint)
                .createdAt(LocalDateTime.now())
                .build();

        Qualification saved = qualificationRepository.save(qualification);
        return mapToResponse(saved);
    }

    @Transactional(readOnly = true)
    public List<QualificationResponse> getAllQualifications() {
        return qualificationRepository.findAll().stream()
                .map(this::mapToResponse)
                .collect(Collectors.toList());
    }

    @Transactional(readOnly = true)
    public QualificationResponse getByCertificateNumber(String certNumber) {
        Qualification qualification = qualificationRepository.findByCertificateNumber(certNumber)
                .orElseThrow(() -> new ResourceNotFoundException("Qualification not found with certificate number: " + certNumber));
        return mapToResponse(qualification);
    }

    @Transactional(readOnly = true)
    public List<QualificationResponse> search(String query) {
        return qualificationRepository.searchQualifications(query).stream()
                .map(this::mapToResponse)
                .collect(Collectors.toList());
    }

    @Transactional
    public QualificationResponse revokeQualification(Long id, String reason) {
        Qualification qualification = qualificationRepository.findById(id)
                .orElseThrow(() -> new ResourceNotFoundException("Qualification not found with id: " + id));

        qualification.setStatus(QualificationStatus.REVOKED);
        qualification.setRevocationReason(reason);
        qualification.setUpdatedAt(LocalDateTime.now());

        return mapToResponse(qualificationRepository.save(qualification));
    }

    public QualificationResponse mapToResponse(Qualification q) {
        return QualificationResponse.builder()
                .id(q.getId())
                .certificateNumber(q.getCertificateNumber())
                .studentFullName(q.getStudentFullName())
                .studentIdNumber(q.getStudentIdNumber())
                .awardTitle(q.getAwardTitle())
                .majorSpecialization(q.getMajorSpecialization())
                .classification(q.getClassification())
                .awardDate(q.getAwardDate())
                .institutionName(q.getInstitution() != null ? q.getInstitution().getName() : "N/A")
                .institutionCode(q.getInstitution() != null ? q.getInstitution().getInstitutionCode() : "N/A")
                .status(q.getStatus())
                .digitalFingerprint(q.getDigitalFingerprint())
                .revocationReason(q.getRevocationReason())
                .createdAt(q.getCreatedAt())
                .build();
    }
}

package com.devops.qvs.service;

import com.devops.qvs.dto.VerificationRequest;
import com.devops.qvs.dto.VerificationResultDto;
import com.devops.qvs.model.AuditLog;
import com.devops.qvs.model.Qualification;
import com.devops.qvs.model.QualificationStatus;
import com.devops.qvs.model.VerificationStatus;
import com.devops.qvs.repository.QualificationRepository;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.time.LocalDateTime;
import java.util.Optional;

@Service
public class VerificationService {

    private final QualificationRepository qualificationRepository;
    private final CryptoHashService cryptoHashService;
    private final AuditLogService auditLogService;

    public VerificationService(QualificationRepository qualificationRepository,
                               CryptoHashService cryptoHashService,
                               AuditLogService auditLogService) {
        this.qualificationRepository = qualificationRepository;
        this.cryptoHashService = cryptoHashService;
        this.auditLogService = auditLogService;
    }

    @Transactional
    public VerificationResultDto verifyQualification(VerificationRequest request,
                                                     String clientIp,
                                                     String userAgent) {
        String cleanQuery = request.getQuery().trim();

        // Check by Certificate Number or Digital Fingerprint
        Optional<Qualification> opt = qualificationRepository.findByCertificateNumber(cleanQuery.toUpperCase());
        if (opt.isEmpty()) {
            opt = qualificationRepository.findByDigitalFingerprint(cleanQuery);
        }

        String verifierId = (request.getVerifierName() != null && !request.getVerifierName().isBlank())
                ? request.getVerifierName() + " (" + (request.getVerifierOrganization() != null ? request.getVerifierOrganization() : "Individual") + ")"
                : "Public Verification Portal";

        if (opt.isEmpty()) {
            // Record Audit Failure
            AuditLog log = auditLogService.recordAuditLog(
                    cleanQuery,
                    VerificationStatus.RECORD_NOT_FOUND,
                    verifierId,
                    clientIp,
                    userAgent,
                    cleanQuery,
                    "Unknown Institution",
                    "Verification failed: No matching qualification record found in registry."
            );

            return VerificationResultDto.builder()
                    .verificationStatus(VerificationStatus.RECORD_NOT_FOUND)
                    .message("No authentic academic record found matching query '" + cleanQuery + "'. Please check the certificate number.")
                    .valid(false)
                    .tamperProofCheckPassed(false)
                    .verifiedAt(LocalDateTime.now())
                    .auditLogId(log.getId())
                    .build();
        }

        Qualification q = opt.get();

        // Check if certificate is Revoked
        if (q.getStatus() == QualificationStatus.REVOKED) {
            AuditLog log = auditLogService.recordAuditLog(
                    cleanQuery,
                    VerificationStatus.REVOKED_CREDENTIAL,
                    verifierId,
                    clientIp,
                    userAgent,
                    q.getCertificateNumber(),
                    q.getInstitution().getName(),
                    "Verification warning: Qualification was revoked. Reason: " + q.getRevocationReason()
            );

            return mapToResult(q, VerificationStatus.REVOKED_CREDENTIAL,
                    "WARNING: This qualification was revoked by the issuing institution (" + q.getRevocationReason() + ").",
                    false, true, log.getId());
        }

        // Cryptographic Tamper-Proof Check (Calculate runtime hash and compare against stored signature)
        boolean isTamperProof = cryptoHashService.verifyFingerprint(
                q.getCertificateNumber(),
                q.getStudentFullName(),
                q.getStudentIdNumber(),
                q.getAwardTitle(),
                q.getInstitution().getInstitutionCode(),
                q.getAwardDate(),
                q.getDigitalFingerprint()
        );

        if (!isTamperProof) {
            AuditLog log = auditLogService.recordAuditLog(
                    cleanQuery,
                    VerificationStatus.SUSPICIOUS_OR_ALTERED,
                    verifierId,
                    clientIp,
                    userAgent,
                    q.getCertificateNumber(),
                    q.getInstitution().getName(),
                    "CRITICAL SECURITY ALERT: Cryptographic hash mismatch! Data may have been tampered with."
            );

            return mapToResult(q, VerificationStatus.SUSPICIOUS_OR_ALTERED,
                    "CRITICAL: Digital integrity check failed. The record data has been altered or tampered with.",
                    false, false, log.getId());
        }

        // Success - Authentic & Verified
        AuditLog log = auditLogService.recordAuditLog(
                cleanQuery,
                VerificationStatus.GENUINE_AND_VALID,
                verifierId,
                clientIp,
                userAgent,
                q.getCertificateNumber(),
                q.getInstitution().getName(),
                "Authenticity confirmed. Validated via SHA-256 digital fingerprint."
        );

        return mapToResult(q, VerificationStatus.GENUINE_AND_VALID,
                "AUTHENTIC & VALID: Qualification successfully verified against the institutional registry.",
                true, true, log.getId());
    }

    private VerificationResultDto mapToResult(Qualification q,
                                              VerificationStatus status,
                                              String message,
                                              boolean valid,
                                              boolean tamperPassed,
                                              Long auditLogId) {
        return VerificationResultDto.builder()
                .verificationStatus(status)
                .message(message)
                .valid(valid)
                .tamperProofCheckPassed(tamperPassed)
                .certificateNumber(q.getCertificateNumber())
                .studentFullName(q.getStudentFullName())
                .studentIdNumber(q.getStudentIdNumber())
                .awardTitle(q.getAwardTitle())
                .majorSpecialization(q.getMajorSpecialization())
                .classification(q.getClassification())
                .awardDate(q.getAwardDate())
                .institutionName(q.getInstitution() != null ? q.getInstitution().getName() : "N/A")
                .qualificationStatus(q.getStatus())
                .digitalFingerprint(q.getDigitalFingerprint())
                .revocationReason(q.getRevocationReason())
                .verifiedAt(LocalDateTime.now())
                .auditLogId(auditLogId)
                .build();
    }
}

