/**
 * DevOps Qualification Verification System - Frontend Interactive Client
 */

// Helper to get stored auth token
function getAuthToken() {
    return localStorage.getItem('qvs_token');
}

function getStoredUser() {
    const user = localStorage.getItem('qvs_user');
    return user ? JSON.parse(user) : null;
}

function saveAuthSession(authResponse) {
    localStorage.setItem('qvs_token', authResponse.token);
    localStorage.setItem('qvs_user', JSON.stringify(authResponse));
}

function logout() {
    localStorage.removeItem('qvs_token');
    localStorage.removeItem('qvs_user');
    window.location.href = '/login';
}

// 1. Verification Lookup on Public Portal
async function verifyCredential(queryOverride) {
    const queryInput = document.getElementById('verificationInput');
    const query = queryOverride || (queryInput ? queryInput.value.trim() : '');

    if (!query) {
        alert('Please enter a certificate number, student ID, or digital fingerprint hash.');
        return;
    }

    if (queryInput) queryInput.value = query;

    const resultCard = document.getElementById('resultCard');
    const loadingSpinner = document.getElementById('loadingIndicator');

    if (loadingSpinner) loadingSpinner.style.display = 'block';
    if (resultCard) resultCard.style.display = 'none';

    try {
        const response = await fetch('/api/v1/verify', {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json'
            },
            body: JSON.stringify({
                query: query,
                verifierName: 'Web Portal Visitor',
                verifierOrganization: 'External Inquirer'
            })
        });

        const data = await response.json();
        displayVerificationResult(data);
    } catch (error) {
        console.error('Verification error:', error);
        alert('An error occurred during verification. Please check if the server is running.');
    } finally {
        if (loadingSpinner) loadingSpinner.style.display = 'none';
    }
}

function displayVerificationResult(data) {
    const resultCard = document.getElementById('resultCard');
    if (!resultCard) return;

    // Reset status classes
    resultCard.className = 'result-card status-' + data.verificationStatus;
    resultCard.style.display = 'block';

    const statusBadge = document.getElementById('statusBadge');
    const statusMessage = document.getElementById('statusMessage');
    const certDetails = document.getElementById('certDetails');

    let badgeClass = 'not-found';
    let badgeText = data.verificationStatus.replace(/_/g, ' ');

    if (data.verificationStatus === 'GENUINE_AND_VALID') {
        badgeClass = 'genuine';
        badgeText = '✓ GENUINE & VALID';
    } else if (data.verificationStatus === 'REVOKED_CREDENTIAL') {
        badgeClass = 'revoked';
        badgeText = '⚠ REVOKED CREDENTIAL';
    } else if (data.verificationStatus === 'SUSPICIOUS_OR_ALTERED') {
        badgeClass = 'altered';
        badgeText = '⛔ TAMPERED / INVALID';
    } else {
        badgeClass = 'not-found';
        badgeText = '✕ RECORD NOT FOUND';
    }

    statusBadge.className = 'status-badge ' + badgeClass;
    statusBadge.innerText = badgeText;
    statusMessage.innerText = data.message;

    if (data.certificateNumber) {
        certDetails.style.display = 'block';
        document.getElementById('resStudentName').innerText = data.studentFullName || 'N/A';
        document.getElementById('resStudentId').innerText = data.studentIdNumber || 'N/A';
        document.getElementById('resAwardTitle').innerText = data.awardTitle || 'N/A';
        document.getElementById('resSpecialization').innerText = data.majorSpecialization || 'N/A';
        document.getElementById('resClassification').innerText = data.classification || 'N/A';
        document.getElementById('resInstitution').innerText = data.institutionName || 'N/A';
        document.getElementById('resAwardDate').innerText = data.awardDate || 'N/A';
        document.getElementById('resCertNumber').innerText = data.certificateNumber || 'N/A';
        document.getElementById('resFingerprint').innerText = data.digitalFingerprint || 'N/A';
        document.getElementById('resAuditId').innerText = 'AUDIT-' + (data.auditLogId || 'N/A');
    } else {
        certDetails.style.display = 'none';
    }

    resultCard.scrollIntoView({ behavior: 'smooth' });
}

// 2. Authentication Handling
async function handleLogin(event) {
    event.preventDefault();
    const username = document.getElementById('username').value.trim();
    const password = document.getElementById('password').value.trim();
    const errorMsg = document.getElementById('loginError');

    try {
        const response = await fetch('/api/v1/auth/login', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ username, password })
        });

        if (!response.ok) {
            const err = await response.json();
            if (errorMsg) {
                errorMsg.style.display = 'block';
                errorMsg.innerText = err.message || 'Invalid credentials.';
            }
            return;
        }

        const data = await response.json();
        saveAuthSession(data);
        window.location.href = '/dashboard';
    } catch (e) {
        console.error('Login error:', e);
        if (errorMsg) {
            errorMsg.style.display = 'block';
            errorMsg.innerText = 'Server connection error.';
        }
    }
}

// 3. Load Qualifications on Dashboard
async function loadQualifications() {
    const tableBody = document.getElementById('qualificationsTableBody');
    if (!tableBody) return;

    try {
        const response = await fetch('/api/v1/qualifications');
        const list = await response.json();

        tableBody.innerHTML = '';
        if (list.length === 0) {
            tableBody.innerHTML = '<tr><td colspan="7" style="text-align: center; color: #64748b;">No qualifications found.</td></tr>';
            return;
        }

        list.forEach(q => {
            const row = document.createElement('tr');
            const statusClass = q.status === 'ACTIVE' ? 'color: #059669; font-weight: bold;' : 'color: #dc2626; font-weight: bold;';
            row.innerHTML = `
                <td><strong>${q.certificateNumber}</strong></td>
                <td>${q.studentFullName}<br><small style="color: #64748b;">${q.studentIdNumber}</small></td>
                <td>${q.awardTitle}<br><small style="color: #64748b;">${q.majorSpecialization}</small></td>
                <td>${q.classification}</td>
                <td>${q.institutionName}</td>
                <td><span style="${statusClass}">${q.status}</span></td>
                <td>
                    <button class="chip-btn" onclick="verifyFromDashboard('${q.certificateNumber}')">Verify</button>
                    ${q.status === 'ACTIVE' ? `<button class="chip-btn revoked" onclick="revokeCert(${q.id})">Revoke</button>` : ''}
                </td>
            `;
            tableBody.appendChild(row);
        });
    } catch (e) {
        console.error('Error loading qualifications:', e);
    }
}

function verifyFromDashboard(certNumber) {
    window.location.href = '/?cert=' + encodeURIComponent(certNumber);
}

async function revokeCert(id) {
    const reason = prompt('Please enter reason for revocation:');
    if (!reason) return;

    const token = getAuthToken();
    if (!token) {
        alert('You must be logged in as an Administrator to revoke qualifications.');
        window.location.href = '/login';
        return;
    }

    try {
        const response = await fetch(`/api/v1/qualifications/${id}/revoke?reason=${encodeURIComponent(reason)}`, {
            method: 'PUT',
            headers: {
                'Authorization': 'Bearer ' + token
            }
        });

        if (response.ok) {
            alert('Qualification successfully revoked.');
            loadQualifications();
        } else {
            alert('Failed to revoke qualification. Ensure you have ROLE_ADMIN privileges.');
        }
    } catch (e) {
        console.error('Revoke error:', e);
    }
}

// 4. Register New Qualification
async function handleRegisterQualification(event) {
    event.preventDefault();
    const token = getAuthToken();
    if (!token) {
        alert('Please login to register qualifications.');
        window.location.href = '/login';
        return;
    }

    const payload = {
        certificateNumber: document.getElementById('certNumber').value.trim(),
        studentFullName: document.getElementById('studentName').value.trim(),
        studentIdNumber: document.getElementById('studentId').value.trim(),
        awardTitle: document.getElementById('awardTitle').value.trim(),
        majorSpecialization: document.getElementById('majorSpec').value.trim(),
        classification: document.getElementById('classification').value.trim(),
        awardDate: document.getElementById('awardDate').value,
        institutionId: 1 // Default institution
    };

    try {
        const response = await fetch('/api/v1/qualifications', {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
                'Authorization': 'Bearer ' + token
            },
            body: JSON.stringify(payload)
        });

        if (response.ok) {
            alert('Qualification registered successfully with SHA-256 fingerprint generated!');
            document.getElementById('qualificationForm').reset();
            loadQualifications();
        } else {
            const err = await response.json();
            alert('Failed to register: ' + (err.message || 'Validation error'));
        }
    } catch (e) {
        console.error('Registration error:', e);
    }
}

// 5. Load Audit Logs
async function loadAuditLogs() {
    const tableBody = document.getElementById('auditTableBody');
    if (!tableBody) return;

    try {
        const response = await fetch('/api/v1/audit-logs');
        const logs = await response.json();

        tableBody.innerHTML = '';
        if (logs.length === 0) {
            tableBody.innerHTML = '<tr><td colspan="6" style="text-align: center; color: #64748b;">No verification audit logs recorded yet.</td></tr>';
            return;
        }

        logs.forEach(log => {
            const row = document.createElement('tr');
            let outcomeColor = '#059669';
            if (log.verificationOutcome === 'REVOKED_CREDENTIAL') outcomeColor = '#dc2626';
            else if (log.verificationOutcome === 'SUSPICIOUS_OR_ALTERED') outcomeColor = '#d97706';
            else if (log.verificationOutcome === 'RECORD_NOT_FOUND') outcomeColor = '#64748b';

            row.innerHTML = `
                <td><strong>#${log.id}</strong></td>
                <td>${new Date(log.timestamp).toLocaleString()}</td>
                <td><code>${log.queryParameter}</code></td>
                <td><span style="color: ${outcomeColor}; font-weight: 700;">${log.verificationOutcome}</span></td>
                <td>${log.verifierIdentifier}<br><small style="color: #64748b;">IP: ${log.ipAddress}</small></td>
                <td><small>${log.details || 'N/A'}</small></td>
            `;
            tableBody.appendChild(row);
        });
    } catch (e) {
        console.error('Error loading audit logs:', e);
    }
}

// Auto-run on page load
document.addEventListener('DOMContentLoaded', () => {
    // Check URL parameters for direct verification queries
    const urlParams = new URLSearchParams(window.location.search);
    const certQuery = urlParams.get('cert');
    if (certQuery) {
        verifyCredential(certQuery);
    }

    // Check login state for nav
    const user = getStoredUser();
    const navAuthContainer = document.getElementById('navAuthStatus');
    if (navAuthContainer && user) {
        navAuthContainer.innerHTML = `
            <span style="color: #cbd5e1; font-size: 0.9rem;">Logged in as: <strong>${user.username}</strong> (${user.role})</span>
            <button class="chip-btn revoked" onclick="logout()">Logout</button>
        `;
    }
});

package com.devops.qvs.service;

import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.springframework.test.util.ReflectionTestUtils;

import java.time.LocalDate;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertTrue;

@DisplayName("Unit Tests: Cryptographic Tamper-Evident Hashing Service")
class CryptoHashServiceTest {

    private CryptoHashService cryptoHashService;

    @BeforeEach
    void setUp() {
        cryptoHashService = new CryptoHashService();
        ReflectionTestUtils.setField(cryptoHashService, "salt", "TEST-SALT-KEY-2026");
    }

    @Test
    @DisplayName("Should generate consistent SHA-256 fingerprint for identical inputs")
    void testGenerateFingerprintConsistency() {
        String certNum = "CERT-1001";
        String studentName = "Alice Smith";
        String studentId = "STU-5544";
        String award = "BSc Computer Science";
        String instCode = "INST-01";
        LocalDate date = LocalDate.of(2024, 5, 20);

        String hash1 = cryptoHashService.generateFingerprint(certNum, studentName, studentId, award, instCode, date);
        String hash2 = cryptoHashService.generateFingerprint(certNum, studentName, studentId, award, instCode, date);

        assertNotNull(hash1);
        assertEquals(64, hash1.length(), "SHA-256 hex string should be 64 characters long");
        assertEquals(hash1, hash2, "Hashing identical parameters must yield identical fingerprint");
    }

    @Test
    @DisplayName("Should successfully verify valid fingerprint")
    void testVerifyFingerprintSuccess() {
        String certNum = "CERT-2002";
        String studentName = "Bob Johnson";
        String studentId = "STU-7788";
        String award = "MSc Artificial Intelligence";
        String instCode = "INST-02";
        LocalDate date = LocalDate.of(2023, 10, 15);

        String generatedHash = cryptoHashService.generateFingerprint(certNum, studentName, studentId, award, instCode, date);
        boolean isValid = cryptoHashService.verifyFingerprint(certNum, studentName, studentId, award, instCode, date, generatedHash);

        assertTrue(isValid, "Fingerprint verification must pass for matching credential data");
    }

    @Test
    @DisplayName("Should detect tampering when credential data is altered")
    void testDetectTamperedCredentialData() {
        String certNum = "CERT-3003";
        String studentName = "Charlie Davis";
        String studentId = "STU-9900";
        String award = "BSc Cyber Security";
        String instCode = "INST-03";
        LocalDate date = LocalDate.of(2024, 1, 10);

        String legitimateHash = cryptoHashService.generateFingerprint(certNum, studentName, studentId, award, instCode, date);

        // Attempt verification with modified/tampered student name
        boolean tamperedNameCheck = cryptoHashService.verifyFingerprint(
                certNum, "Charlie Davis FORGED", studentId, award, instCode, date, legitimateHash
        );
        assertFalse(tamperedNameCheck, "Tampered student name must fail hash verification");

        // Attempt verification with modified award title
        boolean tamperedAwardCheck = cryptoHashService.verifyFingerprint(
                certNum, studentName, studentId, "PhD in Artificial Intelligence", instCode, date, legitimateHash
        );
        assertFalse(tamperedAwardCheck, "Tampered award title must fail hash verification");
    }
}

